function showNumber(value){const raw=String(value).trim();if(!/^(?:\d+|\d{1,3}(?:,\d{3})+)$/.test(raw)||Number(raw.replaceAll(',',''))>1000000){el('error').textContent='Enter a whole number from 0 to 1,000,000.';el('number').setAttribute('aria-invalid','true');el('result').hidden=true;return;}el('number').removeAttribute('aria-invalid');el('error').textContent='';el('result').hidden=false;const n=Number(raw.replaceAll(',','')),r=api.composeRollResult(n),pos=ranks.get(r.totalScore);selectedNumber=n;el('number-label').textContent=String(n);const tier=palette.getCardRarityTier(r.totalScore),tierStyle=palette.getRarityTailwindByTier(tier);const artifact=palette.RARITY_ARTIFACT_STYLES[tier];el('hero').className='relative overflow-hidden inline-flex items-center justify-center rounded-xl px-8 py-5 border-3 bg-gradient-to-br '+artifact.background+' '+artifact.border+' '+artifact.glow+' '+artifact.shadow;el('number-label').className='relative z-10 font-roll font-bold tabular-nums '+artifact.textColor;el('ep-pill').className='type-data inline-flex items-center font-semibold px-3 py-1 rounded-full '+tierStyle.bgClass+' '+tierStyle.textClass+' '+tierStyle.borderClass;const percent=(1000001-(pos.rank-1)-pos.tied)/1000001*100;el('percentile').textContent=percent>=50?'Top '+(100-percent).toFixed(2)+'%':'Bottom '+percent.toFixed(2)+'%';el('percentile').className='type-ui font-medium '+(percent>=50?'text-emerald-600 dark:text-emerald-400':'text-red-500');el('badge-count').textContent=r.badges.length+' badges earned · '+r.badges.filter(b=>b.isScoring).length+' scoring';el('tier').className='type-label px-2 py-0.5 rounded-sm '+tierStyle.bgClass+' '+tierStyle.textClass+' '+tierStyle.borderClass;el('tier').textContent=tier;el('rank').textContent='#'+fmt(pos.rank);el('tie').textContent=pos.tied===1?'This score belongs to this number alone.':fmt(pos.tied)+' numbers share this score (positions '+fmt(pos.rank)+'–'+fmt(pos.rank+pos.tied-1)+').';el('score').textContent=fmt(r.totalScore);el('above').textContent=fmt(pos.rank-1);el('below').textContent=fmt(1000001-(pos.rank-1)-pos.tied);el('badges').replaceChildren(...r.badges.filter(b=>b.isScoring).map(b=>badge(b,true)));const other=r.badges.filter(b=>!b.isScoring);el('other').hidden=!other.length;el('other-label').textContent=other.length+' additional badges · excluded by family rules';el('other-badges').replaceChildren(...other.map(b=>badge(b,false)));}
function renderMatches(){const begin=matchPage*100,end=Math.min(begin+100,matchCount),buttons=[];for(let i=begin;i<end;i++){const n=order[matchStart+i],b=document.createElement('button');b.type='button';b.textContent=fmt(n);b.addEventListener('click',()=>showNumber(n));buttons.push(b);}el('match-list').replaceChildren(...buttons);el('page-label').textContent=fmt(begin+1)+'–'+fmt(end)+' of '+fmt(matchCount);el('previous').disabled=matchPage===0;el('next').disabled=end===matchCount;}
function show(){el('matches').hidden=true;const mode=el('mode').value;if(mode==='number'){showNumber(el('number').value);return;}el('result').hidden=true;const raw=el('number').value.trim(),n=Number(raw.replaceAll(',',''));if(!/^(?:\d+|\d{1,3}(?:,\d{3})+)$/.test(raw)||!Number.isSafeInteger(n)||n<0||(mode==='rank'&&(n<1||n>1000001))){el('error').textContent=mode==='rank'?'Enter a rank from 1 to 1,000,001.':'Enter a non-negative whole EP score.';el('number').setAttribute('aria-invalid','true');return;}el('number').removeAttribute('aria-invalid');el('error').textContent='';let score=n,pos;
if(mode==='ep')pos=ranks.get(n);else{let lo=0,hi=hist.length-1;while(lo<=hi){const mid=(lo+hi)>>1,p=ranks.get(hist[mid][0]);if(n<p.rank)hi=mid-1;else if(n>=p.rank+p.tied)lo=mid+1;else{pos=p;score=hist[mid][0];break;}}}
if(!pos){el('error').textContent='No number has exactly '+fmt(n)+' EP.';return;}matchStart=pos.rank-1;matchCount=pos.tied;matchPage=0;el('matches').hidden=false;el('matches-title').textContent=fmt(matchCount)+(matchCount===1?' number':' numbers')+' · '+fmt(score)+' EP';el('matches-note').textContent=(mode==='rank'&&n!==pos.rank?'Position '+fmt(n)+' falls in a tie. ':'')+'Rank #'+fmt(pos.rank)+(pos.tied>1?' · occupies positions '+fmt(pos.rank)+'–'+fmt(pos.rank+pos.tied-1):'')+'. Select a number to see its badges.';renderMatches();showNumber(order[matchStart]);}
function setMode(){const mode=el('mode').value;el('input-label').textContent=mode==='number'?'Choose a whole number from 0 to 1,000,000':mode==='ep'?'Enter an exact EP score':'Choose a rank or position from 1 to 1,000,001';el('number').value='';el('number').placeholder=mode==='number'?'e.g. 4':mode==='ep'?'e.g. 120380990':'e.g. 1';el('error').textContent='';el('number').removeAttribute('aria-invalid');el('matches').hidden=true;el('result').hidden=true;}
el('theme').addEventListener('click',()=>{const dark=document.documentElement.classList.toggle('dark');el('theme').textContent=dark?'☀ Light':'☾ Dark';el('theme').setAttribute('aria-label',dark?'Switch to light theme':'Switch to dark theme');});el('mode').addEventListener('change',setMode);el('previous').addEventListener('click',()=>{matchPage--;renderMatches();});el('next').addEventListener('click',()=>{matchPage++;renderMatches();});
el('form').addEventListener('submit',e=>{e.preventDefault();show();});document.querySelectorAll('[data-number]').forEach(b=>b.addEventListener('click',()=>{el('mode').value='number';setMode();el('number').value=b.dataset.number;show();}));el('random').addEventListener('click',()=>{el('mode').value='number';setMode();el('number').value=Math.floor(Math.random()*1000001);show();});show();
